begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(8);
insert into auth.users(id,email) values('f1111111-1111-4111-8111-111111111111','sync-boundary@example.com');
update public.profiles set role='student',onboarding_completed=true where id='f1111111-1111-4111-8111-111111111111';
insert into public.memberships(user_id,plan,billing_integration,activation_source,status,product_code,current_period_started_at,current_period_ends_at) values('f1111111-1111-4111-8111-111111111111','premium','toss','toss_payment','active','student_premium',now(),now()+interval '30 days');
insert into public.membership_entitlements(user_id,feature_key,enabled,source) values('f1111111-1111-4111-8111-111111111111','cloud-sync',true,'toss_payment');
insert into public.cloud_focus_sessions(user_id,entity_id,payload,version,device_id) values('f1111111-1111-4111-8111-111111111111','canonical-locked','{"ownerUserId":"f1111111-1111-4111-8111-111111111111","status":"active","endsAt":"2099-01-01T00:00:00Z"}',1,'device');
insert into public.cloud_schedules(user_id,entity_id,payload,version,device_id) values('f1111111-1111-4111-8111-111111111111','canonical-plan','{"ownerUserId":"f1111111-1111-4111-8111-111111111111","selfDepositPoints":1000}',1,'device');
set local role authenticated;
set local request.jwt.claim.sub='f1111111-1111-4111-8111-111111111111';
select throws_ok($$select public.apply_cloud_mutation(gen_random_uuid(),'focus-session','canonical-locked','upsert',1,'{"status":"success"}','device')$$,'P0001','canonical data requires lifecycle RPC','canonical status cannot be overwritten');
select throws_ok($$select public.apply_cloud_mutation(gen_random_uuid(),'focus-session','canonical-locked','delete',1,null,'device')$$,'P0001','canonical data requires lifecycle RPC','canonical session cannot be deleted through sync');
select throws_ok($$select public.apply_cloud_mutation(gen_random_uuid(),'schedule','canonical-plan','upsert',1,'{"id":"canonical-plan"}','device')$$,'P0001','canonical data requires lifecycle RPC','canonical plan cannot be downgraded to legacy');
select throws_ok($$select public.apply_cloud_mutation(gen_random_uuid(),'focus-session','forged','upsert',0,'{"id":"forged","ownerUserId":"f1111111-1111-4111-8111-111111111111","status":"success"}','device')$$,'P0001','canonical data requires lifecycle RPC','new canonical payload cannot be forged');
select throws_ok($$select public.apply_cloud_mutation(gen_random_uuid(),'schedule','forged-plan','upsert',0,'{"id":"forged-plan","selfDepositPoints":1000}','device')$$,'P0001','canonical data requires lifecycle RPC','financial plan fields cannot enter generic sync');
select is(public.apply_cloud_mutation(gen_random_uuid(),'schedule','legacy-plan','upsert',0,'{"id":"legacy-plan","startAt":"2026-10-02T00:00:00Z","endAt":"2026-10-02T01:00:00Z"}','device')->>'status','applied','legacy plan remains syncable');
select is(public.apply_cloud_mutation(gen_random_uuid(),'focus-session','legacy-session','upsert',0,'{"id":"legacy-session","scheduleId":"legacy-plan","status":"completed","dateKey":"2026-10-02","startedAt":"2026-10-02T00:00:00Z","endedAt":"2026-10-02T01:00:00Z","pausedAt":null,"accumulatedFocusSeconds":3600,"distractionSeconds":0,"idleSeconds":0,"blockedAttemptCount":0,"checkInCount":0}','device')->>'status','applied','legacy local session remains syncable');
select throws_ok($$select public.apply_cloud_mutation(gen_random_uuid(),'focus-session','legacy-session','upsert',1,'{"id":"legacy-session","scheduleId":"canonical-plan","status":"completed"}','device')$$,'P0001','canonical data requires lifecycle RPC','legacy shape cannot reference a canonical plan');
select * from finish();
rollback;
